const oDisc = (x, z, r, v) => { for (let zz = z - r; zz <= z + r; zz += OG.c) for (let xx = x - r; xx <= x + r; xx += OG.c) if (Math.hypot(xx - x, zz - z) <= r){ const k = oIdx(xx, zz); if (k >= 0 && !OG.a[k]) OG.a[k] = v; } };

// ---------- hand-drawn landscape (local metres, from the real layout) ----------
// Memorial Glade: the great lawn north of Doe Library inside the curve of University Drive
const GLADE = [[-200, -128], [-160, -138], [-122, -152], [-97, -165], [-64, -166], [-45, -152], [-38, -130], [-42, -115], [-66, -101], [-70, -86], [-132, -66], [-176, -79], [-186, -104]];
// the lawns north-west of VLSB and at the West Crescent (Faculty Glade and the others come from the mapped grass)
