  V.c('#d3cec2'); prism(V, offsetPoly(pod, 0.01), g0 - 2.5, g0, true); V.c('#cfc9bc'); capV(V, pod, g0);
  V.c('#e2ded4'); for (const [su, sv] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]){ for (const [a, b] of [[[su*15, sv*15], [su*7, sv*15]], [[su*15, sv*15], [su*15, sv*7]]]){
      const A = F(a[0], 0, a[1]), B = F(b[0], 0, b[1]); V.q([A[0], g0, A[2]], [B[0], g0, B[2]], [B[0], g0 + 1.1, B[2]], [A[0], g0 + 1.1, A[2]]); } }
